# ---------- main ----------
def write_batch(ids, label):
    assert len(ids) == 20, (label, len(ids))
    for cid in ids:
        assert cid in P, cid
        rec = {"case_id": cid, "prediction_text": P[cid]["prediction_text"], "basis": P[cid]["basis"], "confidence": P[cid]["confidence"], "trigger": P[cid]["trigger"]}
        path = os.path.join(OUT, cid + ".json")
        with open(path, "w", encoding="utf-8") as f:
            json.dump(rec, f, ensure_ascii=False, indent=1)
    print(label, "written", len(ids))
def verify(ids):
    n = 0
    for cid in ids:
        path = os.path.join(OUT, cid + ".json")
        with open(path, encoding="utf-8") as f:
            rec = json.load(f)
        assert rec["case_id"] == cid
        for k in ("prediction_text", "basis", "confidence", "trigger"):
            assert k in rec, (cid, k)
        for b in ("changed_main", "reserve_used", "disputed", "reason"):
            assert b in rec["trigger"], (cid, b)
        assert isinstance(rec["confidence"], float) and 0 <= rec["confidence"] <= 1
        n += 1
    return n
if __name__ == "__main__":
    os.makedirs(OUT, exist_ok=True)
    assert set(B09).isdisjoint(B10) and len(set(B09 + B10)) == 40
    write_batch(B09, "B09")
    assert verify(B09) == 20
    write_batch(B10, "B10")
    assert verify(B10) == 20
    ids = B09 + B10
    cm = sum(1 for i in ids if P[i]["trigger"]["changed_main"])
    ru = sum(1 for i in ids if P[i]["trigger"]["reserve_used"])
    di = sum(1 for i in ids if P[i]["trigger"]["disputed"])
    total_bytes = sum(os.path.getsize(os.path.join(OUT, i + ".json")) for i in ids)
    print("TOTAL", verify(ids), "changed_main", cm, "reserve_used", ru, "disputed", di, "bytes", total_bytes)
